import { execFileSync } from "node:child_process";
import { mkdirSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { dirname, join } from "node:path";
import { advisoryScan } from "../support/advisory-scan.js";

// The UI catalog (app/src/ui/CATALOG.md) is generated by scripts/ui-catalog.mjs. Its freshness on
// the real repo is advisory, like the structural map's (docs/COACHES.md, #4074): every edit to a
// listed module's call site can move a line number, so a red would fire on unrelated PRs. The
// generator's own behaviour, below, is an ordinary unit test and blocks.
const SCRIPT = join(process.cwd(), "scripts/ui-catalog.mjs");

describe("ui catalog freshness (advisory)", () => {
  it("reports a stale app/src/ui/CATALOG.md without blocking CI", () => {
    advisoryScan(SCRIPT, undefined, ["--check"]);
  });
});

function run(root: string, args: string[] = []): number {
  try {
    execFileSync("node", [SCRIPT, ...args], { cwd: root, stdio: "pipe" });
    return 0;
  } catch (err) {
    return (err as { status: number }).status;
  }
}

function seed(root: string, files: Record<string, string>): void {
  for (const [path, body] of Object.entries(files)) {
    mkdirSync(dirname(join(root, path)), { recursive: true });
    writeFileSync(join(root, path), body);
  }
}

const CHIP = `/**
 * A small label for what kind of account a row belongs to.
 * @whenNot the row needs a status, use a pill
 */
export function Chip({ kind }: { readonly kind: "bot" | "human" }): string {
  return kind;
}
`;

describe("ui catalog generator (seeded fixtures)", () => {
  let root: string;
  beforeEach(() => {
    root = mkdtempSync(join(tmpdir(), "ui-catalog-fixture-"));
    const importers: Record<string, string> = {};
    for (let i = 1; i <= 5; i++) {
      importers[`app/src/routes/r${i}.tsx`] =
        `import { Wide } from "../shell/wide";\nexport const x${i} = Wide(${i});\n`;
    }
    seed(root, {
      "app/src/ui/index.ts": 'export { Chip } from "./chip";\n',
      "app/src/ui/chip.tsx": CHIP,
      "app/src/shell/wide.ts":
        "/** Doubles a number. */\nexport function Wide(n: number): number {\n  return n * 2;\n}\n",
      "app/src/shell/narrow.ts": "/** Used once. */\nexport const Narrow = 1;\n",
      "app/src/routes/home.tsx":
        'import { Chip } from "../ui";\nexport const home = Chip({ kind: "bot" });\n',
      "app/src/routes/one.tsx":
        'import { Narrow } from "../shell/narrow";\nexport const one = Narrow;\n',
      ...importers,
    });
  });
  afterEach(() => rmSync(root, { recursive: true, force: true }));

  it("lists every primitive and only the shell modules with five or more importers", () => {
    expect(run(root)).toBe(0);
    const catalog = readFileSync(join(root, "app/src/ui/CATALOG.md"), "utf8");
    expect(catalog).toContain("### Chip");
    expect(catalog).toContain("- job: A small label for what kind of account a row belongs to.");
    expect(catalog).toContain('- props: `{ kind: "bot" | "human" }`');
    expect(catalog).toContain("- when not to use: the row needs a status, use a pill");
    expect(catalog).toContain(
      '- usage: `export const home = Chip({ kind: "bot" });` — `app/src/routes/home.tsx:2`',
    );
    expect(catalog).toContain("### Wide");
    expect(catalog).toContain("- signature: `(n: number)`");
    expect(catalog).toContain("- importers: 5");
    expect(catalog).not.toContain("Narrow");
  });

  it("--check passes on a fresh catalog and exits 1 once a source change makes it stale", () => {
    expect(run(root, ["--check"])).toBe(1);
    run(root);
    expect(run(root, ["--check"])).toBe(0);
    seed(root, { "app/src/ui/chip.tsx": CHIP.replace("A small label", "A tiny label") });
    expect(run(root, ["--check"])).toBe(1);
  });
});
